public static int countMatches(final String str, final String sub) {
		if (isEmptyString(str) || isEmptyString(sub)) {
			return 0;
		}
		int count = 0, idx = 0;
		while ((idx = str.indexOf(sub, idx)) != -1) {
			count++;
			idx += sub.length();
		}
		return count;
	}

