protected void processContextConfig(URL contextXml) {

        if (log.isDebugEnabled())
            log.debug("Processing context [" + context.getName() 
                    + "] configuration file [" + contextXml + "]");

        InputSource source = null;
        InputStream stream = null;

        try {
            source = new InputSource(contextXml.toString());
            stream = contextXml.openStream();

            // Add as watched resource so that cascade reload occurs if a default
            // config file is modified/added/removed
            if ("file".equals(contextXml.getProtocol())) {
                context.addWatchedResource(
                        (new File(contextXml.toURI())).getAbsolutePath());
            }
        } catch (Exception e) {
            log.error(sm.getString("contextConfig.contextMissing",  
                      contextXml) , e);
        }

        if (source == null)
            return;
        synchronized (contextDigester) {
            try {
                source.setByteStream(stream);
                contextDigester.setClassLoader(this.getClass().getClassLoader());
                contextDigester.setUseContextClassLoader(false);
                contextDigester.push(context.getParent());
                contextDigester.push(context);
                XmlErrorHandler errorHandler = new XmlErrorHandler();
                contextDigester.setErrorHandler(errorHandler);
                contextDigester.parse(source);
                if (errorHandler.getWarnings().size() > 0 ||
                        errorHandler.getErrors().size() > 0) {
                    errorHandler.logFindings(log, contextXml.toString());
                    ok = false;
                }
                if (log.isDebugEnabled())
                    log.debug("Successfully processed context [" + context.getName() 
                            + "] configuration file [" + contextXml + "]");
            } catch (SAXParseException e) {
                log.error(sm.getString("contextConfig.contextParse",
                        context.getName()), e);
                log.error(sm.getString("contextConfig.defaultPosition",
                                 "" + e.getLineNumber(),
                                 "" + e.getColumnNumber()));
                ok = false;
            } catch (Exception e) {
                log.error(sm.getString("contextConfig.contextParse",
                        context.getName()), e);
                ok = false;
            } finally {
                contextDigester.reset();
                try {
                    if (stream != null) {
                        stream.close();
                    }
                } catch (IOException e) {
                    log.error(sm.getString("contextConfig.contextClose"), e);
                }
            }
        }
    }

public XWikiDocument getDocument(XWikiDocument doc, XWikiContext context) throws XWikiException
    {
        String currentWiki = context.getWikiId();
        try {
            context.setWikiId(doc.getDocumentReference().getWikiReference().getName());

            try {
                // Indicate the the async context manipulated documents
                getAsyncContext().useEntity(doc.getDocumentReferenceWithLocale());
            } catch (Exception e) {
                // If the AsyncContext component does not work then we are not in an asynchronous context anyway
                LOGGER.debug("Failed to register the document in the asynchronous context", e);
            }

            return getStore().loadXWikiDoc(doc, context);
        } finally {
            context.setWikiId(currentWiki);
        }
    }

