@SuppressWarnings("unchecked")
  static void addMpeg7Metadata(SolrInputDocument doc, MediaPackage mediaPackage, Mpeg7Catalog mpeg7) {

    // Check for multimedia content
    if (!mpeg7.multimediaContent().hasNext()) {
      logger.warn("Mpeg-7 doesn't contain  multimedia content");
      return;
    }

    // Get the content duration by looking at the first content track. This
    // of course assumes that all tracks are equally long.
    MultimediaContent<? extends MultimediaContentType> mc = mpeg7.multimediaContent().next();
    MultimediaContentType mct = mc.elements().next();
    MediaTime mediaTime = mct.getMediaTime();
    Schema.setDcExtent(doc, mediaTime.getMediaDuration().getDurationInMilliseconds());

    // Check if the keywords have been filled by (manually) added dublin
    // core data. If not, look for the most relevant fields in mpeg-7.
    SortedSet<TextAnnotation> sortedAnnotations = null;
    if (!"".equals(Schema.getOcKeywords(doc))) {
      sortedAnnotations = new TreeSet<TextAnnotation>(new Comparator<TextAnnotation>() {
        @Override
        public int compare(TextAnnotation a1, TextAnnotation a2) {
          if ((RELEVANCE_BOOST * a1.getRelevance() + a1.getConfidence()) > (RELEVANCE_BOOST * a2.getRelevance() + a2
                  .getConfidence()))
            return -1;
          else if ((RELEVANCE_BOOST * a1.getRelevance() + a1.getConfidence()) < (RELEVANCE_BOOST * a2.getRelevance() + a2
                  .getConfidence()))
            return 1;
          return 0;
        }
      });
    }

    // Iterate over the tracks and extract keywords and hints
    Iterator<MultimediaContent<? extends MultimediaContentType>> mmIter = mpeg7.multimediaContent();
    int segmentCount = 0;

    while (mmIter.hasNext()) {
      MultimediaContent<?> multimediaContent = mmIter.next();

      // We need to process visual segments first, due to the way they are handled in the ui.
      for (Iterator<?> iterator = multimediaContent.elements(); iterator.hasNext();) {

        MultimediaContentType type = (MultimediaContentType) iterator.next();
        if (!(type instanceof Video) && !(type instanceof AudioVisual))
          continue;

        // for every segment in the current multimedia content track

        Video video = (Video) type;
        Iterator<VideoSegment> vsegments = (Iterator<VideoSegment>) video.getTemporalDecomposition().segments();
        while (vsegments.hasNext()) {
          VideoSegment segment = vsegments.next();

          StringBuffer segmentText = new StringBuffer();
          StringBuffer hintField = new StringBuffer();

          // Collect the video text elements to a segment text
          SpatioTemporalDecomposition spt = segment.getSpatioTemporalDecomposition();
          if (spt != null) {
            for (VideoText videoText : spt.getVideoText()) {
              if (segmentText.length() > 0)
                segmentText.append(" ");
              segmentText.append(videoText.getText().getText());
              // TODO: Add hint on bounding box
            }
          }

          // Add keyword annotations
          Iterator<TextAnnotation> textAnnotations = segment.textAnnotations();
          while (textAnnotations.hasNext()) {
            TextAnnotation textAnnotation = textAnnotations.next();
            Iterator<?> kwIter = textAnnotation.keywordAnnotations();
            while (kwIter.hasNext()) {
              KeywordAnnotation keywordAnnotation = (KeywordAnnotation) kwIter.next();
              if (segmentText.length() > 0)
                segmentText.append(" ");
              segmentText.append(keywordAnnotation.getKeyword());
            }
          }

          // Add free text annotations
          Iterator<TextAnnotation> freeIter = segment.textAnnotations();
          if (freeIter.hasNext()) {
            Iterator<FreeTextAnnotation> freeTextIter = freeIter.next().freeTextAnnotations();
            while (freeTextIter.hasNext()) {
              FreeTextAnnotation freeTextAnnotation = freeTextIter.next();
              if (segmentText.length() > 0)
                segmentText.append(" ");
              segmentText.append(freeTextAnnotation.getText());
            }
          }

          // add segment text to solr document
          Schema.setSegmentText(doc, new DField<String>(segmentText.toString(), Integer.toString(segmentCount)));

          // get the segments time properties
          MediaTimePoint timepoint = segment.getMediaTime().getMediaTimePoint();
          MediaDuration duration = segment.getMediaTime().getMediaDuration();

          // TODO: define a class with hint field constants
          hintField.append("time=" + timepoint.getTimeInMilliseconds() + "\n");
          hintField.append("duration=" + duration.getDurationInMilliseconds() + "\n");

          // Look for preview images. Their characteristics are that they are
          // attached as attachments with a flavor of preview/<something>.
          String time = timepoint.toString();
          for (Attachment slide : mediaPackage.getAttachments(MediaPackageElements.PRESENTATION_SEGMENT_PREVIEW)) {
            MediaPackageReference ref = slide.getReference();
            if (ref != null && time.equals(ref.getProperty("time"))) {
              hintField.append("preview");
              hintField.append(".");
              hintField.append(ref.getIdentifier());
              hintField.append("=");
              hintField.append(slide.getURI().toString());
              hintField.append("\n");
            }
          }

          logger.trace("Adding segment: " + timepoint.toString());
          Schema.setSegmentHint(doc, new DField<String>(hintField.toString(), Integer.toString(segmentCount)));

          // increase segment counter
          segmentCount++;
        }
      }
    }

    // Put the most important keywords into a special solr field
    if (sortedAnnotations != null) {
      Schema.setOcKeywords(doc, importantKeywordsString(sortedAnnotations).toString());
    }
  }

public Page<ConfigInfoAggr> findConfigInfoAggrLike(final int pageNo, final int pageSize, ConfigKey[] configKeys,
                                                       boolean blacklist) {

        String sqlCountRows = "select count(*) from config_info_aggr where ";
        String sqlFetchRows
            = "select data_id,group_id,tenant_id,datum_id,app_name,content from config_info_aggr where ";
        String where = " 1=1 ";
        // 白名单，请同步条件为空，则没有符合条件的配置
        if (configKeys.length == 0 && blacklist == false) {
            Page<ConfigInfoAggr> page = new Page<ConfigInfoAggr>();
            page.setTotalCount(0);
            return page;
        }
        PaginationHelper<ConfigInfoAggr> helper = new PaginationHelper<ConfigInfoAggr>();
        List<String> params = new ArrayList<String>();
        boolean isFirst = true;

        for (ConfigKey configInfoAggr : configKeys) {
            String dataId = configInfoAggr.getDataId();
            String group = configInfoAggr.getGroup();
            String appName = configInfoAggr.getAppName();
            if (StringUtils.isBlank(dataId)
                && StringUtils.isBlank(group)
                && StringUtils.isBlank(appName)) {
                break;
            }
            if (blacklist) {
                if (isFirst) {
                    isFirst = false;
                    where += " and ";
                } else {
                    where += " and ";
                }

                where += "(";
                boolean isFirstSub = true;
                if (!StringUtils.isBlank(dataId)) {
                    where += " data_id not like ? ";
                    params.add(generateLikeArgument(dataId));
                    isFirstSub = false;
                }
                if (!StringUtils.isBlank(group)) {
                    if (!isFirstSub) {
                        where += " or ";
                    }
                    where += " group_id not like ? ";
                    params.add(generateLikeArgument(group));
                    isFirstSub = false;
                }
                if (!StringUtils.isBlank(appName)) {
                    if (!isFirstSub) {
                        where += " or ";
                    }
                    where += " app_name != ? ";
                    params.add(appName);
                    isFirstSub = false;
                }
                where += ") ";
            } else {
                if (isFirst) {
                    isFirst = false;
                    where += " and ";
                } else {
                    where += " or ";
                }
                where += "(";
                boolean isFirstSub = true;
                if (!StringUtils.isBlank(dataId)) {
                    where += " data_id like ? ";
                    params.add(generateLikeArgument(dataId));
                    isFirstSub = false;
                }
                if (!StringUtils.isBlank(group)) {
                    if (!isFirstSub) {
                        where += " and ";
                    }
                    where += " group_id like ? ";
                    params.add(generateLikeArgument(group));
                    isFirstSub = false;
                }
                if (!StringUtils.isBlank(appName)) {
                    if (!isFirstSub) {
                        where += " and ";
                    }
                    where += " app_name = ? ";
                    params.add(appName);
                    isFirstSub = false;
                }
                where += ") ";
            }
        }

        try {
            Page<ConfigInfoAggr> result = helper.fetchPage(jt, sqlCountRows
                    + where, sqlFetchRows + where, params.toArray(), pageNo,
                pageSize, CONFIG_INFO_AGGR_ROW_MAPPER);
            return result;
        } catch (CannotGetJdbcConnectionException e) {
            fatalLog.error("[db-error] " + e.toString(), e);
            throw e;
        }
    }

private void doSnoopTest(RequestDescriptor desc) throws Exception {

        final int ajpPacketSize = 16000;

        Map<String, String> requestInfo = desc.getRequestInfo();
        Map<String, String> contextInitParameters = desc.getContextInitParameters();
        Map<String, String> contextAttributes = desc.getContextAttributes();
        Map<String, String> headers = desc.getHeaders();
        Map<String, String> attributes = desc.getAttributes();
        Map<String, String> params = desc.getParams();

        Tomcat tomcat = getTomcatInstance();
        tomcat.getConnector().setProperty("packetSize", Integer.toString(ajpPacketSize));

        // No file system docBase required
        Context ctx = tomcat.addContext("", null);

        Tomcat.addServlet(ctx, "snoop", new SnoopServlet());
        ctx.addServletMapping("/", "snoop");

        SimpleAjpClient ajpClient = new SimpleAjpClient(ajpPacketSize);

        if (requestInfo.get("REQUEST-QUERY-STRING") != null &&
            params.size() > 0) {
            throw(new IllegalArgumentException("Request setting " +
                "'REQUEST-QUERY-STRING' and explicit params not allowed " +
                "together"));
        }

        String value;
        int bodySize = 0;
        Map<String, String> savedRequestInfo = new HashMap<String, String>();
        for (String name: requestInfo.keySet()) {
            value = requestInfo.get(name);
            if (name.equals("REQUEST-METHOD")) {
                ajpClient.setMethod(value);
            } else if (name.equals("REQUEST-PROTOCOL")) {
                ajpClient.setProtocol(value);
            } else if (name.equals("REQUEST-URI")) {
                ajpClient.setUri(value);
            } else if (name.equals("REQUEST-REMOTE-HOST")) {
                /* request.getRemoteHost() will default to
                 * request.getRemoteAddr() unless enableLookups is set. */
                tomcat.getConnector().setEnableLookups(true);
                ajpClient.setRemoteHost(value);
            } else if (name.equals("REQUEST-REMOTE-ADDR")) {
                ajpClient.setRemoteAddr(value);
            } else if (name.equals("REQUEST-SERVER-NAME")) {
                ajpClient.setServerName(value);
            } else if (name.equals("REQUEST-SERVER-PORT")) {
                ajpClient.setServerPort(Integer.parseInt(value));
            } else if (name.equals("REQUEST-IS-SECURE")) {
                ajpClient.setSsl(Boolean.parseBoolean(value));
            } else if (name.equals("REQUEST-LOCAL-ADDR")) {
                savedRequestInfo.put(name, value);
            } else if (name.equals("REQUEST-REMOTE-PORT")) {
                savedRequestInfo.put(name, value);
            } else if (name.equals("REQUEST-REMOTE-USER") ||
                       name.equals("REQUEST-ROUTE") ||
                       name.equals("REQUEST-SECRET") ||
                       name.equals("REQUEST-AUTH-TYPE") ||
                       name.equals("REQUEST-QUERY-STRING")) {
                savedRequestInfo.put(name, value);
            } else if (name.equals("REQUEST-CONTENT-LENGTH")) {
                headers.put("CONTENT-LENGTH", value);
            } else if (name.equals("REQUEST-BODY-SIZE")) {
                savedRequestInfo.put(name, value);
                bodySize = Integer.parseInt(value);
            } else if (name.equals("REQUEST-CONTENT-TYPE")) {
                headers.put("CONTENT-TYPE", value);
            /* Not yet implemented or not (easily) possible to implement
             * "REQUEST-LOCAL-NAME"
             * "REQUEST-LOCAL-PORT"
             * "REQUEST-SCHEME"
             * "REQUEST-URL"
             * "REQUEST-CONTEXT-PATH"
             * "REQUEST-SERVLET-PATH"
             * "REQUEST-PATH-INFO"
             * "REQUEST-PATH-TRANSLATED"
             * "REQUEST-USER-PRINCIPAL"
             * "REQUEST-CHARACTER-ENCODING"
             * "REQUEST-LOCALE"
             * "SESSION-REQUESTED-ID"
             * "SESSION-REQUESTED-ID-COOKIE"
             * "SESSION-REQUESTED-ID-URL"
             * "SESSION-REQUESTED-ID-VALID"
             */
            } else {
                throw(new IllegalArgumentException("Request setting '" + name + "' not supported"));
            }
        }

        ServletContext sc = ctx.getServletContext();
        for (String name: contextInitParameters.keySet()) {
            sc.setInitParameter(name, contextInitParameters.get(name));
        }
        for (String name: contextAttributes.keySet()) {
            sc.setAttribute(name, contextAttributes.get(name));
        }

        /* Basic request properties must be set before this call */
        TesterAjpMessage forwardMessage = ajpClient.createForwardMessage();

        for (String name: savedRequestInfo.keySet()) {
            value = savedRequestInfo.get(name);
            if (name.equals("REQUEST-LOCAL-ADDR")) {
                forwardMessage.addAttribute("AJP_LOCAL_ADDR", value);
            } else if (name.equals("REQUEST-REMOTE-PORT")) {
                forwardMessage.addAttribute("AJP_REMOTE_PORT", value);
            } else if (name.equals("REQUEST-REMOTE-USER")) {
                /* request.getRemoteUser() will not trust the AJP
                 * info if tomcatAuthentication is set. */
                tomcat.getConnector().setProperty("tomcatAuthentication", "false");
                forwardMessage.addAttribute(0x03, value);
            } else if (name.equals("REQUEST-AUTH-TYPE")) {
                /* request.getAuthType() will not trust the AJP
                 * info if tomcatAuthentication is set. */
                tomcat.getConnector().setProperty("tomcatAuthentication", "false");
                forwardMessage.addAttribute(0x04, value);
            } else if (name.equals("REQUEST-QUERY-STRING")) {
                forwardMessage.addAttribute(0x05, value);
            } else if (name.equals("REQUEST-ROUTE")) {
                forwardMessage.addAttribute(0x06, value);
            } else if (name.equals("REQUEST-SECRET")) {
                forwardMessage.addAttribute(0x0C, value);
            } else if (name.equals("REQUEST-BODY-SIZE")) {
                // NO-OP
            } else {
                throw(new IllegalArgumentException("Request setting '" + name + "' not supported"));
            }
        }

        if (params.size() > 0) {
            StringBuilder query = new StringBuilder();
            boolean sep = false;
            for (String name: params.keySet()) {
                if (sep) {
                    query.append("&");
                } else {
                    sep = true;
                }
                query.append(name);
                query.append("=");
                query.append(params.get(name));
            }
            forwardMessage.addAttribute(0x05, query.toString());
        }

        for (String name: headers.keySet()) {
            value = headers.get(name);
            name = name.toUpperCase(Locale.ENGLISH);
            if (name.equals("ACCEPT")) {
                forwardMessage.addHeader(0xA001, value);
            } else if (name.equals("ACCEPT-CHARSET")) {
                forwardMessage.addHeader(0xA002, value);
            } else if (name.equals("ACCEPT-ENCODING")) {
                forwardMessage.addHeader(0xA003, value);
            } else if (name.equals("ACCEPT-LANGUAGE")) {
                forwardMessage.addHeader(0xA004, value);
            } else if (name.equals("AUTHORIZATION")) {
                forwardMessage.addHeader(0xA005, value);
            } else if (name.equals("CONNECTION")) {
                forwardMessage.addHeader(0xA006, value);
            } else if (name.equals("CONTENT-TYPE")) {
                forwardMessage.addHeader(0xA007, value);
            } else if (name.equals("CONTENT-LENGTH")) {
                forwardMessage.addHeader(0xA008, value);
            } else if (name.equals("COOKIE")) {
                forwardMessage.addHeader(0xA009, value);
            } else if (name.equals("COOKIE2")) {
                forwardMessage.addHeader(0xA00A, value);
            } else if (name.equals("HOST")) {
                forwardMessage.addHeader(0xA00B, value);
            } else if (name.equals("PRAGMA")) {
                forwardMessage.addHeader(0xA00C, value);
            } else if (name.equals("REFERER")) {
                forwardMessage.addHeader(0xA00D, value);
            } else if (name.equals("USER-AGENT")) {
                forwardMessage.addHeader(0xA00E, value);
            } else {
                forwardMessage.addHeader(name, value);
            }
        }
        for (String name: attributes.keySet()) {
            value = attributes.get(name);
            forwardMessage.addAttribute(name, value);
        }
        // Complete the message
        forwardMessage.end();

        tomcat.start();
        ajpClient.setPort(getPort());
        ajpClient.connect();

        TesterAjpMessage responseHeaders = null;
        if (bodySize == 0) {
            responseHeaders = ajpClient.sendMessage(forwardMessage);
        } else {
            TesterAjpMessage bodyMessage = ajpClient.createBodyMessage(new byte[bodySize]);
            responseHeaders = ajpClient.sendMessage(forwardMessage, bodyMessage);
            // Expect back a request for more data (which will be empty and
            // trigger end of stream in Servlet)
            validateGetBody(responseHeaders);
            bodyMessage = ajpClient.createBodyMessage(new byte[0]);
            responseHeaders = ajpClient.sendMessage(bodyMessage);
        }

        // Expect 3 packets: headers, body, end
        validateResponseHeaders(responseHeaders, 200, "OK");

        String body = extractResponseBody(ajpClient.readMessage());
        RequestDescriptor result = SnoopResult.parse(body);

        /* AJP attributes result in Coyote Request attributes, which are
         * not listed by request.getAttributeNames(), so SnoopServlet
         * does not see them. Delete attributes before result comparison. */
        desc.getAttributes().clear();

        result.compare(desc);

        validateResponseEnd(ajpClient.readMessage(), true);
    }

