public static <T> int nullSafeCompare(boolean nullsFirst, Comparable<T> o1, T o2) {
		if (o1 == null && o2 == null) {
			return 0;
		} else if (o1 == null) {
			return nullsFirst ? -1 : 1;
		} else if (o2 == null) {
			return nullsFirst ? 1 : -1;
		} else {
			return o1.compareTo(o2);
		}
	}

