            hosts = newHosts;
            hostMapping.getRealHost().removeAlias(hostMapping);
        }

    }

static boolean isFragment(Cur start, Cur end)
    {
        assert !end.isAttr();

        start.push();
        end.push();

        int numDocElems = 0;
        boolean isFrag = false;

        while (!start.isSamePos(end))
        {
            int k = start.kind();

            if (k == ATTR)
                break;

            if (k == TEXT && !isWhiteSpace(start.getCharsAsString(-1)))
            {
                isFrag = true;
                break;
            }

            if (k == ELEM && ++numDocElems > 1)
            {
                isFrag = true;
                break;
            }

            // Move to next token

            assert k != ATTR;

            if (k != TEXT)
                start.toEnd();

            start.next();
        }

        start.pop();
        end.pop();

        return isFrag || numDocElems != 1;
    }

public void setReadListener(ReadListener listener) {
        if (listener == null) {
            throw new NullPointerException(
                    sm.getString("request.nullReadListener"));
        }
        if (getReadListener() != null) {
            throw new IllegalStateException(
                    sm.getString("request.readListenerSet"));
        }
        // Note: This class is not used for HTTP upgrade so only need to test
        //       for async
        AtomicBoolean result = new AtomicBoolean(false);
        action(ActionCode.ASYNC_IS_ASYNC, result);
        if (!result.get()) {
            throw new IllegalStateException(
                    sm.getString("request.notAsync"));
        }

        this.listener = listener;

        // The container is responsible for the first call to
        // listener.onDataAvailable(). If isReady() returns true, the container
        // needs to call listener.onDataAvailable() from a new thread. If
        // isReady() returns false, the socket will be registered for read and
        // the container will call listener.onDataAvailable() once data arrives.
        // Must call isFinished() first as a call to isReady() if the request
        // has been finished will register the socket for read interest and that
        // is not required.
        if (!isFinished() && isReady()) {
            synchronized (nonBlockingStateLock) {
                // Ensure we don't get multiple read registrations
                registeredForRead = true;
                // Need to set the fireListener flag otherwise when the
                // container tries to trigger onDataAvailable, nothing will
                // happen
                fireListener = true;
            }
            action(ActionCode.DISPATCH_READ, null);
            if (!ContainerThreadMarker.isContainerThread()) {
                // Not on a container thread so need to execute the dispatch
                action(ActionCode.DISPATCH_EXECUTE, null);
            }
        }
    }

@ParameterizedTest(name = IntegrationTestSupport.PARAMETERIZED_TEST_NAME_PATTERN)
    @MethodSource("allCombinations")
    public void testSendOneWayCommandSucceeds(
            final AmqpCommandEndpointConfiguration endpointConfig,
            final VertxTestContext ctx) throws InterruptedException {

        final String commandTargetDeviceId = endpointConfig.isSubscribeAsGateway()
                ? helper.setupGatewayDeviceBlocking(tenantId, deviceId, 5)
                : deviceId;

        final int commandsToSend = 60;
        final Checkpoint commandsReceived = ctx.checkpoint(commandsToSend);

        final AtomicInteger counter = new AtomicInteger();
        testSendCommandSucceeds(
                ctx,
                commandTargetDeviceId,
                endpointConfig,
                (cmdReceiver, cmdResponseSender) -> (delivery, msg) -> {
                    ctx.verify(() -> {
                        assertThat(msg.getReplyTo()).isNull();
                        assertThat(msg.getSubject()).isEqualTo("setValue");
                        assertThat(msg.getAddress())
                                .isEqualTo(endpointConfig.getCommandMessageAddress(tenantId, commandTargetDeviceId));
                    });
                    log.debug("received command [name: {}]", msg.getSubject());
                    ProtonHelper.accepted(delivery, true);
                    cmdReceiver.flow(1);
                    commandsReceived.flag();
                }, payload -> {
                    return helper.sendOneWayCommand(
                            tenantId,
                            commandTargetDeviceId,
                            "setValue",
                            "text/plain",
                            payload,
                            // set "forceCommandRerouting" message property so that half the command are rerouted via the AMQP network
                            IntegrationTestSupport.newCommandMessageProperties(() -> counter.getAndIncrement() >= commandsToSend / 2),
                            IntegrationTestSupport.getSendCommandTimeout());
                }, commandsToSend);
    }

