private @Nullable OffsetTime getOffsetTime(int i) throws SQLException {
    byte[] value = getRawValue(i);
    if (value == null) {
      return null;
    }

    int col = i - 1;
    int oid = fields[col].getOID();

    if (oid == Oid.TIMETZ) {
      if (isBinary(i)) {
        return getTimestampUtils().toOffsetTimeBin(value);
      } else {
        return getTimestampUtils().toOffsetTime(castNonNull(getString(i)));
      }
    }

    throw new PSQLException(
        GT.tr("Cannot convert the column of type {0} to requested type {1}.",
            Oid.toString(oid), "java.time.OffsetTime"),
        PSQLState.DATA_TYPE_MISMATCH);
  }

private boolean recursiveDelete(File file) {
        // Try deleting file before assuming file is a directory
        // to prevent following symbolic links.
        if (file.delete()) {
            return true;
        }
        File[] files = file.listFiles();
        if (files != null) {
            for (File each : files) {
                if (!recursiveDelete(each)) {
                    return false;
                }
            }
        }
        return file.delete();
    }

