protected void appendHeaders(Message message, HttpServletRequest request) throws JMSException {
        message.setJMSCorrelationID(jmsCorrelationID);
        if (jmsReplyTo != null && jmsReplyTo.trim().length() > 0) {
            message.setJMSReplyTo(ActiveMQDestination.createDestination(jmsReplyTo, ActiveMQDestination.QUEUE_TYPE));
        }
        message.setJMSType(jmsType);

        // now lets add all of the parameters
        Map map = request.getParameterMap();
        if (map != null) {
            for (Iterator iter = map.entrySet().iterator(); iter.hasNext();) {
                Map.Entry entry = (Map.Entry)iter.next();
                String name = (String)entry.getKey();
                Object value = entry.getValue();
                if (isValidPropertyName(name)) {
                    if (value instanceof String[]) {
                        String[] array = (String[])value;
                        if (array.length > 0) {
                            value = array[0];
                        } else {
                            value = null;
                        }
                    }
                    if (value instanceof String) {
                        String text = value.toString().trim();
                        if (text.length() == 0) {
                            value = null;
                        } else {
                            value = text;
                        }
                    }
                    if (value != null) {
                        message.setObjectProperty(name, value);
                    }
                }
            }
        }
    }

private void select_SelectResults(SelectResults selectResults, Object principal,
      List<SelectResultRow> list, AtomicInteger nestedObjectCount, InternalCache cache)
      throws GfJsonException {
    for (Object object : selectResults) {
      // Post processing
      object = cache.getSecurityService().postProcess(principal, null, null, object, false);

      if (object instanceof Struct) {
        StructImpl impl = (StructImpl) object;
        GfJsonObject jsonStruct = getJSONForStruct(impl, nestedObjectCount);
        if (logger.isDebugEnabled()) {
          logger.debug("SelectResults : Adding select json string : {}", jsonStruct);
        }
        list.add(
            new SelectResultRow(DataCommandResult.ROW_TYPE_STRUCT_RESULT, jsonStruct.toString()));
      } else if (JsonUtil.isPrimitiveOrWrapper(object.getClass())) {
        if (logger.isDebugEnabled()) {
          logger.debug("SelectResults : Adding select primitive : {}", object);
        }
        list.add(new SelectResultRow(DataCommandResult.ROW_TYPE_PRIMITIVE, object));
      } else {
        if (logger.isDebugEnabled()) {
          logger.debug("SelectResults : Bean Results class is {}", object.getClass());
        }
        String str = toJson(object);
        GfJsonObject jsonBean;
        try {
          jsonBean = new GfJsonObject(str);
        } catch (GfJsonException e) {
          logger.error(e.getMessage(), e);
          jsonBean = new GfJsonObject();
          try {
            jsonBean.put("msg", e.getMessage());
          } catch (GfJsonException e1) {
            logger.warn("Ignored GfJsonException:", e1);
          }
        }
        if (logger.isDebugEnabled()) {
          logger.debug("SelectResults : Adding bean json string : {}", jsonBean);
        }
        list.add(new SelectResultRow(DataCommandResult.ROW_TYPE_BEAN, jsonBean.toString()));
      }
    }
  }

public void saveDocument(XWikiDocument document, String comment, boolean isMinorEdit, XWikiContext context)
        throws XWikiException
    {
        String currentWiki = context.getWikiId();

        try {
            // Switch to document wiki
            context.setWikiId(document.getDocumentReference().getWikiReference().getName());

            // Make sure the document is ready to be saved
            XWikiDocument originalDocument = prepareDocumentForSave(document, comment, isMinorEdit, context);

            // Notify listeners about the document about to be created or updated

            // Note that for the moment the event being send is a bridge event, as we are still passing around
            // an XWikiDocument as source and an XWikiContext as data.
            beforeSave(document, context);

            // Delete existing document if we replace with a new one
            if (document.isNew()) {
                if (!originalDocument.isNew()) {
                    // We don't want to notify about this delete since from outside world point of view it's an update
                    // and not a delete+create
                    deleteDocument(originalDocument, true, false, context);
                }
            } else {
                // Put attachments to remove in recycle bin
                if (hasAttachmentRecycleBin(context)) {
                    for (XWikiAttachmentToRemove attachment : document.getAttachmentsToRemove()) {
                        if (attachment.isToRecycleBin()) {
                            // Make sure the attachment will be deleted with its history
                            attachment.getAttachment().loadArchive(context);
                            getAttachmentRecycleBinStore().saveToRecycleBin(attachment.getAttachment(),
                                context.getUser(), new Date(), context, true);
                        }
                    }
                }
            }

            // Actually save the document.
            getStore().saveXWikiDoc(document, context);

            // Since the store#saveXWikiDoc resets originalDocument, we need to temporarily put it
            // back to send notifications.
            XWikiDocument newOriginal = document.getOriginalDocument();

            try {
                document.setOriginalDocument(originalDocument);

                // Notify listeners about the document having been created or updated

                // First the legacy notification mechanism

                // Then the new observation module
                // Note that for the moment the event being send is a bridge event, as we are still passing around
                // an XWikiDocument as source and an XWikiContext as data.
                // The old version is made available using doc.getOriginalDocument()
                afterSave(document, context);
            } catch (Exception ex) {
                LOGGER.error("Failed to send document save notification for document ["
                    + getDefaultEntityReferenceSerializer().serialize(document.getDocumentReference()) + "]", ex);
            } finally {
                document.setOriginalDocument(newOriginal);
            }
        } finally {
            context.setWikiId(currentWiki);
        }
    }

