    public int getProgress() {
        long d;
        lock.readLock().lock();
        try {
            if (executable == null) {
                return -1;
            }
            d = Executables.getEstimatedDurationFor(executable);
        } finally {
            lock.readLock().unlock();
        }
        if (d <= 0) {
            return -1;
        }

        int num = (int) (getElapsedTime() * 100 / d);
        if (num >= 100) {
            num = 99;
        }
        return num;
    }

