public static <T> Iterator<T> sortedIterator(Iterator<T> it, Comparator<T> comparator) {
		List<T> list = new ArrayList<>();
		while (it.hasNext()) {
			list.add(it.next());
		}

		Collections.sort(list, comparator);
		return list.iterator();
	}

