public long getEstimatedRemainingTimeMillis() {
        long d;
        lock.readLock().lock();
        try {
            if (executable == null) {
                return -1;
            }

            d = Executables.getEstimatedDurationFor(executable);
        } finally {
            lock.readLock().unlock();
        }
        if (d < 0) {
            return -1;
        }

        long eta = d - getElapsedTime();
        if (eta <= 0) {
            return -1;
        }

        return eta;
    }

