public static void createUserLoginPasswordHistory(GenericValue userLogin) throws GenericEntityException{
        int passwordChangeHistoryLimit = 0;
        Delegator delegator = userLogin.getDelegator();
        String userLoginId = userLogin.getString("userLoginId");
        String currentPassword = userLogin.getString("currentPassword");
        try {
            passwordChangeHistoryLimit = EntityUtilProperties.getPropertyAsInteger("security", "password.change.history.limit", 0).intValue();
        } catch (NumberFormatException nfe) {
            //No valid value is found so don't bother to save any password history
            passwordChangeHistoryLimit = 0;
        }
        if (passwordChangeHistoryLimit == 0 || passwordChangeHistoryLimit < 0) {
            // Not saving password history, so return from here.
            return;
        }
        EntityQuery eq = EntityQuery.use(delegator)
                .from("UserLoginPasswordHistory")
                .where("userLoginId", userLoginId)
                .orderBy("-fromDate")
                .cursorScrollInsensitive();
        Timestamp nowTimestamp = UtilDateTime.nowTimestamp();

        try (EntityListIterator eli = eq.queryIterator()) {
            GenericValue pwdHist;
            if ((pwdHist = eli.next()) != null) {
                // updating password so set end date on previous password in history
                pwdHist.set("thruDate", nowTimestamp);
                pwdHist.store();
                // check if we have hit the limit on number of password changes to be saved. If we did then delete the oldest password from history.
                eli.last();
                int rowIndex = eli.currentIndex();
                if (rowIndex==passwordChangeHistoryLimit) {
                    eli.afterLast();
                    pwdHist = eli.previous();
                    pwdHist.remove();
                }
            }
        }

        // save this password in history
        GenericValue userLoginPwdHistToCreate = delegator.makeValue("UserLoginPasswordHistory", UtilMisc.toMap("userLoginId", userLoginId,"fromDate", nowTimestamp));
        userLoginPwdHistToCreate.set("currentPassword", currentPassword);
        userLoginPwdHistToCreate.create();
    }

public void renameUser(final String oldName, final String newName) throws Exception {
        update();

        m_writeLock.lock();

        try {
            // Get the old data
            if (m_users.containsKey(oldName)) {
                final User data = m_users.get(oldName);
                if (data == null) {
                    m_users.remove(oldName);
                    throw new Exception("UserFactory:rename the data contained for old user " + oldName + " is null");
                } else {
                    // Rename the user in the user map.
                    m_users.remove(oldName);
                    data.setUserId(newName);
                    m_users.put(newName, data);

                    // Refresh the groups config first
                    m_groupManager.update();

                    // Rename the user in the group.
                    m_groupManager.renameUser(oldName, newName);

                    // Rename the user in the view.
                    // viewFactory.renameUser(oldName, newName);
                }
            } else {
                throw new Exception("UserFactory:rename the old user name " + oldName + " is not found");
            }

            _saveCurrent();
        } finally {
            m_writeLock.unlock();
        }
    }

