            + " FROM (                               "
            + "   SELECT id FROM config_info         "
            + "   WHERE tenant_id LIKE ?                  "
            + "   ORDER BY id LIMIT ?, ?             "
            + " ) g, config_info t                   "
            + " WHERE g.id = t.id                    ";

        final int totalCount = configInfoCount(tenant);
        int pageCount = totalCount / pageSize;
