public static String prettyTrim(String str, int maxLength) {
		if (maxLength < 5) {
			throw new IllegalArgumentException("Algorithm for 'prettyTrim' works only with length >= 5. "
					+ "Supplied length is " + maxLength);
		}

		if (str == null || str.length() <= maxLength) {
			return str;
		}

		// find a section to cut off
		int len = maxLength - 3;
		int startLen = len / 2;
		int endLen = len - startLen;

		return str.substring(0, startLen) + "..." + str.substring(str.length() - endLen);
	}

private @PolyNull String trimMoney(@PolyNull String s) {
    if (s == null) {
      return null;
    }

    // if we don't have at least 2 characters it can't be money.
    if (s.length() < 2) {
      return s;
    }

    // Handle Money
    char ch = s.charAt(0);

    // optimise for non-money type: return immediately with one check
    // if the first char cannot be '(', '$' or '-'
    if (ch > '-') {
      return s;
    }

    if (ch == '(') {
      s = "-" + PGtokenizer.removePara(s).substring(1);
    } else if (ch == '$') {
      s = s.substring(1);
    } else if (ch == '-' && s.charAt(1) == '$') {
      s = "-" + s.substring(2);
    }

    return s;
  }

